UPDATE zangraf_products SET data=jsonb_set(jsonb_set(data,'{options,sheets}','["10 lâminas", "15 lâminas", "20 lâminas", "25 lâminas", "30 lâminas", "35 lâminas", "40 lâminas", "45 lâminas", "50 lâminas", "55 lâminas", "60 lâminas"]'::jsonb),'{description}',to_jsonb(replace(data->>'description','15 lâminas (30 páginas)','10 a 60 lâminas (20 a 120 páginas)'))),updated_at=now()
WHERE coalesce(data->>'kind','album')='album' AND EXISTS(SELECT 1 FROM first_run);
